const phoneNos = [9311644155];
const amount = 50;
const balance_credited = [];
const transaction_created_but_not_credited = [];
const transaction_creation_failed = [];
const user_not_found = [];
const message_not_sent = [];
const message_sent = [];
const template = "image_akb_wallet";
const variables = [50];
const imgUrl =
    "https://growaasan-prod-assets.s3.ap-south-1.amazonaws.com/public-assets/coupons/B6tvnaeIuAudNaYyH4dH3SJmIqnqGgtyKbu9ddxv.jpg";
let vars = "";
variables.forEach((variable, index) => {
    vars += `&var${index + 1}=${variable}`;
});

const addWalletBalance = async (phoneNos) => {
    console.log(`Processing ${phoneNos.length} phone numbers...`);
    const batchSize = 100;

    for (let i = 0; i < phoneNos.length; i += batchSize) {
        const batch = phoneNos.slice(i, i + batchSize);
        console.log(`Processing batch ${i + 1} to ${i + batch.length}...`);

        const batchResults = await Promise.allSettled(
            batch.map(async (phoneNo) => {
                try {
                    const user = await userSchema.findOne({ phoneNo });
                    if (!user) {
                        return { phoneNo, status: "user_not_found" };
                    }

                    const now = new Date();
                    const walletTransaction =
                        await walletTransactionSchema.create({
                            userId: user._id,
                            amount: amount,
                            type: "credit",
                            message: "SPECIAL CASH FOR YOU",
                            status: "success",
                            created: now,
                            updated: now,
                            date: now,
                            marketingTag: "8feb_wallet_marketing_new_user",
                        });

                    if (!walletTransaction) {
                        return {
                            phoneNo,
                            status: "transaction_creation_failed",
                        };
                    }

                    const updatedUser = await userSchema.findOneAndUpdate(
                        { phoneNo },
                        { $inc: { walletBalance: amount } }
                    );

                    if (!updatedUser) {
                        return {
                            phoneNo,
                            status: "transaction_created_but_not_credited",
                        };
                    }

                    return { phoneNo, status: "balance_credited" };
                } catch (error) {
                    console.error(`Error processing ${phoneNo}:`, error);
                    return { phoneNo, status: "transaction_creation_failed" };
                }
            })
        );

        const balance_credited = batchResults
            .filter((r) => r.value?.status === "balance_credited")
            .map((r) => r.value.phoneNo);
        const transaction_created_but_not_credited = batchResults
            .filter(
                (r) =>
                    r.value?.status === "transaction_created_but_not_credited"
            )
            .map((r) => r.value.phoneNo);
        const transaction_creation_failed = batchResults
            .filter((r) => r.value?.status === "transaction_creation_failed")
            .map((r) => r.value.phoneNo);
        const user_not_found = batchResults
            .filter((r) => r.value?.status === "user_not_found")
            .map((r) => r.value.phoneNo);

        console.log("balance_credited", JSON.stringify(balance_credited));
        console.log(
            "transaction_created_but_not_credited",
            JSON.stringify(transaction_created_but_not_credited)
        );
        console.log(
            "transaction_creation_failed",
            JSON.stringify(transaction_creation_failed)
        );
        console.log("user_not_found", JSON.stringify(user_not_found));

        sendSMSBulk(balance_credited);
    }
};

const sendSMS = async (phoneNo) => {
    const url = `https://api.growaasan.com/api/sendPosCommunication?clietnId=100139&authKey=aWJzLzJvZ08yNmZMcFJmYnFnd2w1Zz09&communicationType=2&waTemplateName=${template}&waTemplateLang=en&country_code=91&customerMobile=${phoneNo}&varCount=${variables.length}${vars}&messageType=image&mediaUrl=${imgUrl}`;
    try {
        const response = await axios.get(url);
        response.status === 200
            ? message_sent.push(phoneNo)
            : message_not_sent.push(phoneNo);
        return JSON.parse(response.data.whatsapp_uniqueid).status === "success";
    } catch (error) {
        console.error(`Error sending SMS to ${phoneNo}:`, error);
        message_not_sent.push(phoneNo);
        return false;
    }
};

const sendSMSBulk = async (phoneNos) => {
    const concurrencyLimit = 10; // Limit concurrent requests
    let successCount = 0;

    const processBatch = async (batch) => {
        const results = await Promise.all(
            batch.map((phoneNo) => sendSMS(phoneNo))
        );
        successCount += results.filter(Boolean).length;
    };

    for (let i = 0; i < phoneNos.length; i += concurrencyLimit) {
        const batch = phoneNos.slice(i, i + concurrencyLimit);
        await processBatch(batch); // Process each batch sequentially
        process.stdout.write(
            `Completed ${i + batch.length} of ${phoneNos.length} \r`
        );
    }

    console.log(`\nTotal Success Count: ${successCount}`);
    console.log("message_sent", JSON.stringify(message_sent.length));
    console.log("message_not_sent", JSON.stringify(message_not_sent));
};
